#!/usr/bin/env python3
"""Compare two key=value config files and summarize differences."""

def load_conf(path):
    """Parse a key=value config file into an ordered dict."""
    conf = {}
    order = []
    with open(path) as f:
        for lineno, line in enumerate(f, 1):
            line = line.strip()
            # Skip blank lines and comments
            if not line or line.startswith('#') or line.startswith(';'):
                continue
            if '=' not in line:
                print(f"warning: {path}:{lineno}: ignoring malformed line: {line!r}")
                continue
            key, _, value = line.partition('=')
            key, value = key.strip(), value.strip()
            if key not in conf:
                order.append(key)
            conf[key] = value
    return conf, order

def main():
    v1, order1 = load_conf('/data/v1.conf')
    v2, order2 = load_conf('/data/v2.conf')

    added   = [k for k in order2 if k not in v1]
    removed = [k for k in order1 if k not in v2]
    changed = [k for k in order1 if k in v2 and v1[k] != v2[k]]
    same    = [k for k in order1 if k in v2 and v1[k] == v2[k]]

    print("Config comparison: /data/v1.conf -> /data/v2.conf")
    print("=" * 52)

    print(f"\nADDED ({len(added)}):")
    if added:
        for k in added:
            print(f"  + {k} = {v2[k]}")
    else:
        print("  (none)")

    print(f"\nREMOVED ({len(removed)}):")
    if removed:
        for k in removed:
            print(f"  - {k} = {v1[k]}")
    else:
        print("  (none)")

    print(f"\nCHANGED ({len(changed)}):")
    if changed:
        for k in changed:
            print(f"  ~ {k}: {v1[k]} -> {v2[k]}")
    else:
        print("  (none)")

    print(f"\nUNCHANGED ({len(same)}): {', '.join(same) if same else '(none)'}")
    print()
    print(f"Summary: {len(added)} added, {len(removed)} removed, "
          f"{len(changed)} changed, {len(same)} unchanged")

if __name__ == '__main__':
    main()
